  const categories = [
    { slug: "sofas", name: "Sofas & Living", description: "Sofas, armchairs and living-room seating." },
    { slug: "beds", name: "Beds & Bedroom", description: "Beds, headboards, wardrobes and bedside furniture." },
    { slug: "dining", name: "Dining", description: "Dining tables, chairs and sideboards." },
    { slug: "storage", name: "Storage", description: "Cabinets, shelving, bookcases and chests." },
    { slug: "lighting", name: "Lighting", description: "Lamps, pendants and ceiling lighting." },
    { slug: "decor", name: "Décor & Accessories", description: "Rugs, cushions, mirrors and decorative objects." },
    { slug: "outdoor", name: "Outdoor", description: "Patio, garden and balcony furniture." },
    { slug: "home-office", name: "Home Office", description: "Desks, office chairs and workspace storage." },
  ];

  const categoryMap: Record<string, any> = {};
  for (const c of categories) {
    categoryMap[c.slug] = await prisma.category.upsert({
      where: { slug: c.slug },
      update: {},
      create: c,
    });
  }

  async function areaSlug(countyName: string, townName: string, areaName: string) {
    const townRec = await prisma.town.findFirst({
      where: { name: townName, county: { name: countyName } },
      include: { areas: true },
    });
    const area = townRec?.areas.find((a) => a.name === areaName);
    return area?.id;
  }

