        serviceAreas: r.serviceAreas,
        phone: r.phone,
        whatsapp: r.whatsapp,
        email: r.email,
        website: r.website,
        instagram: r.instagram,
        facebook: r.facebook,
        tiktok: r.tiktok,
        verified: r.verified,
